{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Healthcare Research Data",
    "url": "http://localhost:7808",
    "widgets_json": {
      "pipeline_vegalite": {
        "name": "Pipeline Mix (Vega-Lite)",
        "description": "Vega-Lite bar spec of pipeline phase mix.",
        "endpoint": "/pipeline-vegalite",
        "type": "chart-vegalite",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "phase",
            "type": "text",
            "label": "Phase",
            "value": "all",
            "description": "Pipeline phase to chart."
          }
        ]
      },
      "catalyst_metric": {
        "name": "Catalysts 30d",
        "description": "Catalysts in the next 30 days.",
        "endpoint": "/catalyst-count",
        "type": "metric",
        "w": 6,
        "h": 4,
        "staleTime": 900000
      },
      "trial_catalysts": {
        "name": "Trial Catalysts",
        "description": "Upcoming clinical trial readouts.",
        "endpoint": "/trial-catalysts",
        "type": "table",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "ticker",
            "type": "endpoint",
            "label": "Ticker",
            "value": "PFE",
            "optionsEndpoint": "/tickers"
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "ticker",
              "headerName": "Ticker",
              "cellDataType": "text"
            },
            {
              "field": "phase",
              "headerName": "Phase",
              "cellDataType": "text"
            },
            {
              "field": "readout_date",
              "headerName": "Readout",
              "cellDataType": "dateString"
            }
          ]
        }
      }
    },
    "apps_json": [
      {
        "name": "Pipeline Chart Live",
        "tabs": {
          "pipeline": {
            "id": "pipeline",
            "name": "Pipeline",
            "layout": [
              {
                "i": "pipeline_vegalite",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "signals": {
            "id": "signals",
            "name": "Signals",
            "layout": [
              {
                "i": "catalyst_metric",
                "x": 0,
                "y": 0,
                "w": 8,
                "h": 5
              }
            ]
          }
        },
        "description": "Vega-Lite pipeline and catalysts."
      }
    ]
  }
}

{
  "done": false,
  "tool": "manage_apps",
  "args": {
    "operation": "instantiate",
    "template_id": "Pipeline Chart Live",
    "dashboard_name": "Pipeline Chart Live Board"
  }
}

{
  "done": false,
  "tool": "manage_apps",
  "args": {
    "operation": "instantiate",
    "template_id": "Pipeline Chart Live",
    "dashboard_name": "Pipeline Chart Live Board",
    "backend_id": "backend_001"
  }
}

{
  "done": false,
  "tool": "add_generative_widget",
  "args": {
    "dashboard_id": "dash_002",
    "data": "Pipeline Chart Live shipped from Healthcare Research Data: Vega-Lite live.",
    "inner_tab": "pipeline",
    "name": "Pipeline Chart Live",
    "widget_type": "note"
  }
}
